import { GENERATORS, BECH32_CONST, BECH32M_CONST } from './charset.mjs';

export function polymod(values) {
  let chk = 1;
  for (const value of values) {
    const top = chk >> 25;
    chk = ((chk & 0x1ffffff) << 5) ^ value;
    for (let i = 0; i < 5; i++) {
      chk ^= ((top >> i) & 1) ? GENERATORS[i] : 0;
    }
  }
  return chk;
}

export function hrpExpand(hrp) {
  const highs = [];
  const lows = [];
  for (const ch of hrp) {
    highs.push(ch.charCodeAt(0) >> 5);
    lows.push(ch.charCodeAt(0) & 31);
  }
  return [...highs, 0, ...lows];
}

export function verifyChecksum(hrp, data) {
  const check = polymod([...hrpExpand(hrp), ...data]);
  if (check === BECH32_CONST) return 'bech32';
  if (check === BECH32M_CONST) return 'bech32m';
  return null;
}

export function createChecksum(hrp, data, spec) {
  const constValue = spec === 'bech32' ? BECH32_CONST : BECH32M_CONST;
  const values = [...hrpExpand(hrp), ...data];
  const mod = polymod([...values, 0, 0, 0, 0, 0, 0]) ^ constValue;
  const ret = [];
  for (let p = 0; p < 6; p++) {
    ret.push((mod >> (5 * (5 - p))) & 31);
  }
  return ret;
}

