import { CHARSET, CHARKEY } from './charset.mjs';
import { verifyChecksum, createChecksum } from './checksum.mjs';

export function bech32Encode(hrp, data, spec) {
  const combined = [...data, ...createChecksum(hrp, data, spec)];
  let out = hrp + '1';
  for (const d of combined) {
    out += CHARSET[d];
  }
  return out;
}

export function bech32Decode(bech) {
  if (typeof bech !== 'string') return [null, null, null];

  let hasLower = false;
  let hasUpper = false;
  for (const ch of bech) {
    const code = ch.charCodeAt(0);
    if (code < 33 || code > 126) return [null, null, null];
    if (ch >= 'a' && ch <= 'z') hasLower = true;
    if (ch >= 'A' && ch <= 'Z') hasUpper = true;
  }
  if (hasLower && hasUpper) return [null, null, null];

  const normalized = bech.toLowerCase();
  const pos = normalized.lastIndexOf('1');
  if (pos < 1 || pos + 7 > normalized.length || normalized.length > 90) {
    return [null, null, null];
  }

  const hrp = normalized.slice(0, pos);
  const dataPart = normalized.slice(pos + 1);
  const data = [];
  for (const ch of dataPart) {
    const v = CHARKEY.get(ch);
    if (v === undefined) return [null, null, null];
    data.push(v);
  }

  const spec = verifyChecksum(hrp, data);
  if (spec === null) return [null, null, null];

  return [hrp, data.slice(0, data.length - 6), spec];
}

