import { bech32Encode, bech32Decode } from './base32.mjs';
import { convertbits } from './convertbits.mjs';

export function encode(hrp, witver, witprog) {
  const spec = witver === 0 ? 'bech32' : 'bech32m';
  const ret = bech32Encode(hrp, [witver, ...witprog], spec);
  const decoded = decode(hrp, ret);
  if (decoded[0] === null || decoded[1] === null) {
    return null;
  }
  return ret;
}

export function decode(hrp, addr) {
  const [hrpgot, data, spec] = bech32Decode(addr);
  if (hrpgot !== hrp || data === null || data.length === 0) {
    return [null, null];
  }

  const witver = data[0];
  const witprog5 = data.slice(1);
  const witprog8 = convertbits(witprog5, 5, 8, false);

  if (witprog8 === null) return [null, null];
  if (witver > 16) return [null, null];
  if (witprog8.length < 2 || witprog8.length > 40) return [null, null];
  if (witver === 0 && witprog8.length !== 20 && witprog8.length !== 32) {
    return [null, null];
  }
  if (witver === 0 && spec !== 'bech32') return [null, null];
  if (witver !== 0 && spec !== 'bech32m') return [null, null];

  return [witver, witprog5];
}

