const OPTIONS = [
  { name: 'a', type: 'str', required: true },
  { name: 'b', type: 'int', required: true },
  { name: 'c', type: 'str', required: true },
];

function fail(message) {
  process.stderr.write(`test16.mjs: error: ${message}\n`);
  process.exit(2);
}

function convert(name, raw, type) {
  if (type === 'int') {
    if (!/^[+-]?\d+$/.test(raw)) {
      fail(`argument --${name}: invalid int value: '${raw}'`);
    }
    return Number.parseInt(raw, 10);
  }
  return raw;
}

export function parseArgs(argv) {
  const values = {};

  for (let i = 0; i < argv.length; i++) {
    const token = argv[i];
    if (!token.startsWith('--')) {
      fail(`unrecognized arguments: ${token}`);
    }

    let name;
    let inlineValue = null;
    const eq = token.indexOf('=');
    if (eq !== -1) {
      name = token.slice(2, eq);
      inlineValue = token.slice(eq + 1);
    } else {
      name = token.slice(2);
    }

    const opt = OPTIONS.find((o) => o.name === name);
    if (!opt) {
      fail(`unrecognized arguments: ${token}`);
    }

    let raw;
    if (inlineValue !== null) {
      raw = inlineValue;
    } else {
      i += 1;
      if (i >= argv.length) {
        fail(`argument --${name}: expected one argument`);
      }
      raw = argv[i];
    }

    values[name] = convert(name, raw, opt.type);
  }

  for (const opt of OPTIONS) {
    if (opt.required && values[opt.name] === undefined) {
      fail(`the following arguments are required: --${opt.name}`);
    }
  }

  return values;
}

