import { parseArgs } from './lib/args.mjs';
import { convertbits } from './bech32/convertbits.mjs';
import { encode, decode } from './bech32/segwit.mjs';

function pyList(arr) {
  return `[${arr.join(', ')}]`;
}

function main() {
  const args = parseArgs(process.argv.slice(2));

  const data = args.c.split(',').map((x) => Number.parseInt(x, 10));

  // Convert 8-bit to 5-bit
  const converted = convertbits(data, 8, 5);
  // Encode segwit address
  const encoded = encode(args.a, args.b, converted);
  // Decode segwit address
  const decoded = decode(args.a, encoded);
  // Convert back to 8-bit
  if (decoded[0] !== null && decoded[1] !== null) {
    const [witver, witprog] = decoded;
    const convertedBack = convertbits(witprog, 5, 8, false);
    console.log(pyList(converted));
    console.log(encoded);
    console.log(witver);
    console.log(pyList(convertedBack));
  }
}

main();

